{
  "segment_function": "introduction to the distinction between labor and work, outlining etymological evidence and historical contempt for labor in ancient thought",
  "claims": [
    {
      "claim": "The proposed distinction between labor and work is unusual, lacking support in pre-modern political thought and modern labor theories, yet is supported by the existence of two etymologically unrelated words for these activities in European languages.",
      "claim_type": "author_position",
      "supporting_excerpt": "The distinction between labor and work which I propose is unusual. The phenomenal evidence in its favor is too striking to be ignored, and yet historically it is a fact that apart from a few scattered remarks, which moreover were never developed even in the theories of their authors, there is hardly anything in either the pre-modern tradition of political thought or in the large body of modern labor theories to support it. Against this scarcity of historical evidence, however, stands one very articulate and obstinate testimony, namely, the simple fact that every European language, ancient and modern, contains two etymologically unrelated words for what we have to come to think of as the same activity, and retains them in the face of their persistent synonymous usage.",
      "support_kind": "direct",
      "qualifications": [
        "apart from a few scattered remarks in the history of thought"
      ],
      "confidence": 1.0
    },
    {
      "claim": "Contempt for laboring originally arose from a striving for freedom from necessity and impatience with effort that left no permanent monument, later spreading to cover all effort as demands of the polis increased.",
      "claim_type": "author_position",
      "supporting_excerpt": "Contempt for laboring, originally arising out of a passionate striving for freedom from necessity and a no less passionate impatience with every effort that left no trace, no monument, no great work worthy of remembrance, spread with the increasing demands of polis life upon the time of the citizens and its insistence on their abstention ( skholē ) from all but political activities, until it covered everything that demanded an effort.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "cheirotechnēs",
      "definition": "The ancient Greek craftsman, corresponding to the German Handwerker."
    },
    {
      "term": "banausoi",
      "definition": "A term used later in antiquity to describe artisans, meaning men whose chief interest is their craft and not the market place."
    }
  ],
  "distinctions": [
    {
      "item_a": "labor",
      "item_b": "work",
      "distinction": "Every European language, ancient and modern, contains two etymologically unrelated words for these activities, and the noun 'labor' never designates the finished product whereas the product itself is invariably derived from the word for work."
    }
  ],
  "examples": [],
  "objections": [],
  "responses": [],
  "references_to_other_sections": [],
  "unresolved_context": [
    "Karl Marx will be criticized in the following chapter.",
    "Benjamin Constant's statement on attacking Rousseau."
  ],
  "must_not_be_lost": [
    "The etymological evidence of two unrelated words across European languages for labor and work.",
    "The historical origins of contempt for labor in the ancient Greek polis and shifting classifications of occupations."
  ]
}

